content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-005

=== 用户原始指令 (query.txt) ===
帮我整个清理卡片 要有按钮 数字会变 点进去能跳应用 能读天气 有红色提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我整个清理卡片 要有按钮 数字会变 点进去能跳应用 能读天气 有红色提示",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询的区县名称",
            "sampleValue": "青浦区"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          },
          "alertLevel": {
            "type": "string",
            "description": "天气或环境预警信息",
            "sampleValue": "高温"
          }
        },
        "updatedAt": {
          "type": "string",
          "description": "端侧完成天气查询和归一化的时间",
          "sampleValue": "09:30"
        }
      },
      "memory": {
        "cleanablePercent": {
          "type": "number",
          "description": "当前可清理内存比例，数字会随设备状态变化",
          "sampleValue": 72
        },
        "cleanableText": {
          "type": "string",
          "description": "可清理内存的短文本数值",
          "sampleValue": "72%"
        },
        "riskText": {
          "type": "string",
          "description": "内存压力红色提示文案",
          "sampleValue": "偏高"
        }
      }
    },
    "ui": {
      "title": {
        "type": "string",
        "description": "卡片标题",
        "sampleValue": "内存清理"
      },
      "actionLabel": {
        "type": "string",
        "description": "主操作按钮文案",
        "sampleValue": "看天气"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_clear.png",
      "description": "清除图标，适合表示内存清理和一键清理动作。"
    },
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色多云天气图标，适合表示当前天气状态。"
    }
  ]
}

